        Button importBase=button("IMPORT YOUR PNG TEMPLATE",green);importBase.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/png").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,REQ_BASE);});body.addView(importBase,new LinearLayout.LayoutParams(-1,dp(54)));
        body.addView(text("Use a transparent PNG from Canva, Photoshop, etc. Leave spaces such as a circle for the player number, then place editable fields over those spots.",12,muted,false));
